using BARANG.Core.Domain.Logistics;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace BARANG.Core.Infrastructure.Persistence.Configurations;
internal static class LogisticsConfig{internal static void Base<T>(EntityTypeBuilder<T>b,string table)where T:class{b.ToTable(table);b.HasKey("Id");b.Property<Guid>("Id").HasColumnName("id");b.Property<Guid>("CompanyId").HasColumnName("company_id");b.HasAlternateKey("CompanyId","Id");}}
internal sealed class PackageConfiguration:IEntityTypeConfiguration<Package>{public void Configure(EntityTypeBuilder<Package>b){LogisticsConfig.Base(b,"packages");b.Property(x=>x.OrderId).HasColumnName("order_id");b.Property(x=>x.PackageNumber).HasColumnName("package_number").HasMaxLength(40);b.Property(x=>x.PackageTypeCode).HasColumnName("package_type_code").HasMaxLength(50);b.Property(x=>x.WeightKg).HasColumnName("weight_kg").HasPrecision(12,3);b.Property(x=>x.LengthCm).HasColumnName("length_cm").HasPrecision(12,3);b.Property(x=>x.WidthCm).HasColumnName("width_cm").HasPrecision(12,3);b.Property(x=>x.HeightCm).HasColumnName("height_cm").HasPrecision(12,3);b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(30);b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.CompletedAtUtc).HasColumnName("completed_at_utc");b.Property(x=>x.CompletedByUserId).HasColumnName("completed_by_user_id");b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasIndex(x=>new{x.CompanyId,x.PackageNumber}).IsUnique();b.HasIndex(x=>new{x.CompanyId,x.OrderId,x.Status});b.HasOne<Domain.Orders.Order>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class PackageItemConfiguration:IEntityTypeConfiguration<PackageItem>{public void Configure(EntityTypeBuilder<PackageItem>b){LogisticsConfig.Base(b,"package_items");b.Property(x=>x.PackageId).HasColumnName("package_id");b.Property(x=>x.OrderId).HasColumnName("order_id");b.Property(x=>x.OrderItemId).HasColumnName("order_item_id");b.Property(x=>x.Quantity).HasColumnName("quantity").HasPrecision(18,4);b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.HasIndex(x=>new{x.CompanyId,x.PackageId,x.OrderItemId}).IsUnique();b.HasIndex(x=>new{x.CompanyId,x.OrderItemId});b.HasOne<Package>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.PackageId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Orders.OrderItem>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderItemId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Orders.Order>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class HandoffConfiguration:IEntityTypeConfiguration<ShippingHandoff>{public void Configure(EntityTypeBuilder<ShippingHandoff>b){LogisticsConfig.Base(b,"shipping_handoffs");b.Property(x=>x.PackageId).HasColumnName("package_id");b.Property(x=>x.WarehouseId).HasColumnName("warehouse_id");b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.ReceivedAtUtc).HasColumnName("received_at_utc");b.Property(x=>x.ReceivedByUserId).HasColumnName("received_by_user_id");b.Property(x=>x.ReleasedAtUtc).HasColumnName("released_at_utc");b.Property(x=>x.ReleasedByUserId).HasColumnName("released_by_user_id");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasIndex(x=>new{x.CompanyId,x.PackageId}).IsUnique();b.HasOne<Package>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.PackageId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Organization.Warehouse>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.WarehouseId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class ShipmentConfiguration:IEntityTypeConfiguration<Shipment>{public void Configure(EntityTypeBuilder<Shipment>b){LogisticsConfig.Base(b,"shipments");b.Property(x=>x.OrderId).HasColumnName("order_id");b.Property(x=>x.ShipmentNumber).HasColumnName("shipment_number").HasMaxLength(40);b.Property(x=>x.CarrierCode).HasColumnName("carrier_code").HasMaxLength(50);b.Property(x=>x.ShippingMethodCode).HasColumnName("shipping_method_code").HasMaxLength(50);b.Property(x=>x.TrackingCode).HasColumnName("tracking_code").HasMaxLength(100);b.Property(x=>x.ShipmentDateUtc).HasColumnName("shipment_date_utc");b.Property(x=>x.ExpectedDeliveryDate).HasColumnName("expected_delivery_date");b.Property(x=>x.DeliveredAtUtc).HasColumnName("delivered_at_utc");b.Property(x=>x.FailedAtUtc).HasColumnName("failed_at_utc");b.Property(x=>x.ReturnedAtUtc).HasColumnName("returned_at_utc");b.Property(x=>x.ReturnWarehouseId).HasColumnName("return_warehouse_id");b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(25);b.Property(x=>x.LastReasonCode).HasColumnName("last_reason_code").HasMaxLength(50);b.Property(x=>x.LastReasonText).HasColumnName("last_reason_text").HasMaxLength(500);b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc");b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasIndex(x=>new{x.CompanyId,x.ShipmentNumber}).IsUnique();b.HasIndex(x=>new{x.CompanyId,x.OrderId,x.Status});b.HasIndex(x=>new{x.CompanyId,x.CarrierCode,x.TrackingCode}).HasFilter("tracking_code IS NOT NULL").IsUnique();b.HasOne<Domain.Orders.Order>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Organization.Warehouse>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.ReturnWarehouseId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class ShipmentPackageConfiguration:IEntityTypeConfiguration<ShipmentPackage>{public void Configure(EntityTypeBuilder<ShipmentPackage>b){LogisticsConfig.Base(b,"shipment_packages");b.Property(x=>x.ShipmentId).HasColumnName("shipment_id");b.Property(x=>x.PackageId).HasColumnName("package_id");b.Property(x=>x.AssignedAtUtc).HasColumnName("assigned_at_utc");b.HasIndex(x=>new{x.CompanyId,x.PackageId}).IsUnique();b.HasOne<Shipment>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.ShipmentId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Package>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.PackageId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class ShipmentHistoryConfiguration:IEntityTypeConfiguration<ShipmentStatusHistory>{public void Configure(EntityTypeBuilder<ShipmentStatusHistory>b){LogisticsConfig.Base(b,"shipment_status_history");b.Property(x=>x.ShipmentId).HasColumnName("shipment_id");b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(25);b.Property(x=>x.OccurredAtUtc).HasColumnName("occurred_at_utc");b.Property(x=>x.ActorUserId).HasColumnName("actor_user_id");b.Property(x=>x.SourceCode).HasColumnName("source_code").HasMaxLength(30);b.Property(x=>x.ReasonCode).HasColumnName("reason_code").HasMaxLength(50);b.Property(x=>x.ReasonText).HasColumnName("reason_text").HasMaxLength(500);b.HasIndex(x=>new{x.CompanyId,x.ShipmentId,x.OccurredAtUtc,x.Id});b.HasOne<Shipment>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.ShipmentId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
internal sealed class ShipmentReturnConfiguration:IEntityTypeConfiguration<ShipmentReturn>{public void Configure(EntityTypeBuilder<ShipmentReturn>b){LogisticsConfig.Base(b,"shipment_returns");b.Property(x=>x.ShipmentId).HasColumnName("shipment_id");b.Property(x=>x.OrderId).HasColumnName("order_id");b.Property(x=>x.OrderItemId).HasColumnName("order_item_id");b.Property(x=>x.Quantity).HasColumnName("quantity").HasPrecision(18,4);b.Property(x=>x.UomCode).HasColumnName("uom_code").HasMaxLength(30);b.Property(x=>x.ReasonCode).HasColumnName("reason_code").HasMaxLength(50);b.Property(x=>x.ReasonText).HasColumnName("reason_text").HasMaxLength(500);b.Property(x=>x.IdempotencyKey).HasColumnName("IdempotencyKey").HasMaxLength(100);b.Property(x=>x.Status).HasColumnName("status").HasConversion<string>().HasMaxLength(20);b.Property(x=>x.RecordedByUserId).HasColumnName("recorded_by_user_id");b.Property(x=>x.RecordedAtUtc).HasColumnName("recorded_at_utc");b.Property(x=>x.Version).HasColumnName("version").IsConcurrencyToken();b.HasIndex(x=>new{x.CompanyId,x.ShipmentId,x.OrderItemId});b.HasIndex(x=>new{x.CompanyId,x.IdempotencyKey}).IsUnique();b.HasOne<Shipment>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.ShipmentId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Orders.Order>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);b.HasOne<Domain.Orders.OrderItem>().WithMany().HasForeignKey(x=>new{x.CompanyId,x.OrderItemId}).HasPrincipalKey(x=>new{x.CompanyId,x.Id}).OnDelete(DeleteBehavior.Restrict);}}
